class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        int cnt[26] = {0};
        for (char c : tasks) cnt[c - 'A']++;
        int maxFreq = 0, numMax = 0;
        for (int i = 0; i < 26; ++i) {
            if (cnt[i] > maxFreq) {
                maxFreq = cnt[i];
                numMax = 1;
            } else if (cnt[i] == maxFreq) {
                ++numMax;
            }
        }
        long long partLen = 1LL * (maxFreq - 1) * (n + 1) + numMax;
        long long total = tasks.size();
        return (int)max(partLen, total);
    }
};
